INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('17f2afb0-b5a9-4964-83ca-6a159b77072b', '(Tentative ) Linguistics Club', 'Linguistics Club seeks to provide extra-curricular engagement for students of all backgrounds who are interested in linguistics. Our primary goal is to encourage members to connect more with linguistics and with each other!', 'Linguistics Club seeks to provide extra-curricular engagement for students of all backgrounds who are interested in linguistics, regardless of whether they are majors/combined majors, minors, hobbyists, or completely new to the field. Linguistics Club aims to host guest speakers, attend conferences, and coordinate a variety of other outings. We also hold more casual and social meetings, such as the Transcription Bee (a non-competitive bee dedicated to phonetic transcription), game nights, and study breaks. Towards the end of a semester, we aim to provide additional guidance for students in the linguistics program by offering an avenue to practice presenting research posters ahead of fairs, as well as offering informal peer advising on course registration. The club&rsquo;s Discord serves as a digital platform for all students who are interested in linguistics to connect and is extremely active. ', '315', 'FALSE', 'fall', 'unrestricted', '00000000-0000-0000-0000-000000000000');
INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('d7737a1e-41ac-4085-b6d8-3fa052669f9f', 'Adopted Student Organization', 'Adopted Student Organization is a safe space for adoptees to connect over shared and diverse experiences.', 'Our mission is to foster a safe space for adoptees to tell their adoption stories and express their feelings, opinions, and thoughts about adoption and other related topics without harsh judgment from others. In addition, we aim to educate anyone interested in adoption-related topics. INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('111b0149-edd4-4be7-a71e-924435d6a31c', 'Automotive Club', 'Automotive Club is a welcoming space for automotive enthusiasts of all levels. Enjoy outings to car meets, go-kart tracks, virtual sim racing, hands-on activities, and talks by experts in the industry. Join us for all things cars!', 'The Automotive Club is where automotive enthusiasts, whether beginners or experts, come together in a warm and inclusive atmosphere. Dive into engaging experiences like exciting outings to car meets, heart-pounding go-kart tracks, immersive virtual sim racing, interactive hands-on activities, and enlightening talks by industry professionals. Fuel your passion for cars and join us on a thrilling journey through all things automotive!', '362', 'TRUE', 'always', 'application', '00000000-0000-0000-0000-000000000000');
INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('7624128c-1785-4e49-8a51-ecf7c3159815', 'Baltic Northeastern Association', 'The Baltic Northeastern Association serves as a home away from home for students from the Baltic countries, as well as an opportunity to share Baltic culture with interested students. ', 'The Baltic Northeastern Association serves as a home away from home for students from the Baltic countries, as well as an opportunity to share Baltic culture with interested students. We will host weekly meetings that can range from cooking sessions, discussions of Baltic culture and language, sharing Baltic traditional dancing and music, and more. ', '67', 'FALSE', 'spring', 'unrestricted', '00000000-0000-0000-0000-000000000000');
INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('fa953d99-8502-4da8-adcd-df9aade992f7', 'Bangladeshi Organization of Networking, Diversity, Heritage, Unity and Support', 'The BONDHUS is dedicated to fostering a sense of home for Bangladeshi students and those interested in Bangladeshi culture, as well as celebrating the rich cultural heritage of Bangladesh.', 'The BONDHUS is dedicated to fostering a sense of home for Bangladeshi students and those interested in Bangladeshi culture. We strive to provide mentorship, build cultural awareness, and offer assistance with college admissions, including hosting events in Bangladesh related to Northeastern University. Our mission is to create an inclusive community that celebrates and promotes the rich heritage of Bangladesh while providing support and growth opportunities for our members. Our target membership includes Bangladeshi international undergraduates and graduates, Bangladeshi diaspora-born undergraduates and graduates, and non-Bangladeshi undergraduates and graduates interested in our culture and mission. We plan to host a wide range of events and initiatives, including:INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('13a6d7e5-36e6-4688-80ea-8ec03dba4b57', 'Binky Patrol', 'Binky Patrol is club that makes blankets by hand to donate to children in hospitals and shelters', 'Binky Patrol is a club that makes blankets by hand to donate to children in hospitals and shelters - if you want to get involved, join the slack with the link below!INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('a171e959-a0b4-496f-be93-d873bc3bb979', 'Biokind Analytics Northeastern', 'Biokind Analytics Northeastern brings together undergraduate data scientists and statisticians across the world to apply classroom learning for meaningful, positive societal impact in their communities.', 'Biokind Analytics Northeastern is a local chapter of the larger nonprofit organization, Biokind Analytics. The club aims to provide Northeastern students with the opportunity to apply data analysis skills and learnings to further the mission of local healthcare non-profit organizations in the Boston region. Our goal is to promote the development of relationships between Northeastern students and healthcare non-profits to better contribute to our local community. ', '845', 'FALSE', 'spring', 'unrestricted', '00000000-0000-0000-0000-000000000000');
INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('85dc14f5-059d-4454-93e9-f8822f6ecad4', 'Black Graduate Student Association ', 'The purpose of Black Graduate Student Association is to enhance scholarly and professional development of graduate students at Northeastern through networking, seminars, forums, workshops, and social gatherings in the Boston Area. ', 'Welcome to the Black Graduate Student Association! Our club is dedicated to enriching the academic and professional growth of graduate students at Northeastern University. Through a variety of networking opportunities, engaging seminars, thought-provoking forums, skill-building workshops, and fun social gatherings in the vibrant city of Boston, we aim to create a supportive community where students can thrive and connect with like-minded peers. Join us to expand your knowledge, build valuable skills, and forge lasting friendships as you navigate your graduate journey!', '537', 'FALSE', 'fall', 'unrestricted', '00000000-0000-0000-0000-000000000000');
INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('2f527dc0-100c-4e38-a7a6-fb304a4bd079', 'Black Pre-Law Association', 'BPLA''s purpose is to nurture a supportive and empowering community for Black undergraduate students interested in pursuing a career in the legal field. ', 'BPLA''s purpose is to nurture a supportive and empowering community for Black undergraduate students interested in pursuing a career in the legal field. We aim to encourage dialogue on social justice/legal issues, academic excellence, personal growth, and professional development.', '355', 'TRUE', 'always', 'unrestricted', '00000000-0000-0000-0000-000000000000');
INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('f16b8337-4665-4671-bcf4-bbb722efdca8', 'Brazilian Jiu Jitsu at Northeastern University', 'BJJ is primarily a ground based martial art focusing on the submission of the opponent through principles of angles, leverage, pressure and timing, in order to achieve submission of the opponent in a skillful and technical way.INSERT INTO "club_tags" ("tag_id", "club_id") VALUES ('41245b1f-2723-4fbb-83ee-b270e589b202', '17f2afb0-b5a9-4964-83ca-6a159b77072b');
